JS = r'''
const search=document.querySelector('#search'), severity=document.querySelector('#severity'), cards=[...document.querySelectorAll('.finding')];
function filter(){const q=search.value.trim().toLowerCase(),s=severity.value;let n=0;for(const c of cards){const show=(!s||c.dataset.severity===s)&&(!q||c.textContent.toLowerCase().includes(q));c.hidden=!show;if(show)n++}document.querySelector('#result-count').textContent=`${n} of ${cards.length} findings`;document.querySelector('#empty').hidden=n!==0;}
search.addEventListener('input',filter);severity.addEventListener('change',filter);
function revealHash(){const el=document.getElementById(location.hash.slice(1));if(el?.classList.contains('finding')&&el.hidden){search.value='';severity.value='';filter();el.scrollIntoView();}}
window.addEventListener('hashchange',revealHash);revealHash();
document.querySelector('#print').addEventListener('click',()=>window.print());
let detailStates=[];window.addEventListener('beforeprint',()=>{detailStates=[...document.querySelectorAll('details')].map(d=>[d,d.open]);for(const [d]of detailStates)d.open=true;document.body.classList.add('printing');});
window.addEventListener('afterprint',()=>{for(const[d,o]of detailStates)d.open=o;document.body.classList.remove('printing');});
'''

document = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><meta name="referrer" content="no-referrer"><title>OpenDeploy — Security Audit · 11 September 2026</title><style>{CSS}</style></head>
<body><a class="skip" href="#findings">Skip to findings</a><div class="topbar"><div class="shell"><div class="brand">OPENDEPLOY / SECURITY REVIEW</div><span>Repository assessment · 11 September 2026</span></div></div>
<header class="hero shell"><div class="eyebrow">Security audit / September 2026</div><h1>Deployment trust boundaries need stronger enforcement.</h1><p class="lede">OpenDeploy has meaningful authentication and access controls, but deployment capabilities can cross into host privileges, other services' identities and protected secrets.</p><div class="meta"><span>Reviewed 11 September 2026 · Australia/Sydney</span><span>Commit <code>{COMMIT[:12]}</code></span><span>Source review + bounded local checks</span></div><div class="scorecard">{stats}<div class="stat-note"><strong>13 actionable findings</strong>Ratings reflect OpenDeploy's deployment and space model. Scanner advisory counts are tracked separately below.</div></div></header>
<nav class="nav" aria-label="Report sections"><div class="shell"><a href="#assessment">Assessment</a><a href="#findings">Findings</a><a href="#remediation">Remediation</a><a href="#dependencies">Dependencies</a><a href="#coverage">Validation</a><button id="print" type="button">Print / save PDF</button></div></nav>
<main class="shell"><section id="assessment"><div class="intro-grid"><div class="callout"><strong>Prioritize the host boundary.</strong><p>Nix exporter execution and host mounts make ordinary deployment authority far more powerful than its space-scoped API grants suggest. Address these paths before treating spaces or agent restrictions as containment for untrusted code.</p><div class="flow" aria-label="Observed escalation path"><span>Deployment permission</span><b aria-hidden="true">→</b><span>Build / mount control</span><b aria-hidden="true">→</b><span>Host data and authority</span></div></div><div class="scope"><p><strong>Scope.</strong> Current Go backend, VanJS/Vite frontend, public/cluster/enrollment API wiring, authorization, PKI, runtime preparation, installer pins and selected dependency paths.</p><p><strong>Threat model.</strong> Remote unauthenticated clients, scoped operators, delegated agents, hostile deployment sources and compromised enrolled workers. Cluster administrators and the host OS already hold substantial trust.</p><p><strong>Boundary of this assessment.</strong> Repository audit, not a production penetration test or certification. Linux mounts, container escapes and exhaustion payloads were not executed. Existing user-docs work was left untouched.</p></div></div>
<p class="small" style="margin-top:22px">Critical = plausible host/control-plane compromise from lesser deployment authority. High = major confidentiality, integrity or shared-service impact under stated prerequisites. Medium = bounded, conditional or availability/hardening exposure. No synthetic CVSS scores were assigned.</p>
<h2 style="margin-top:30px">Finding index</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Evidence level</th></tr></thead><tbody>{index_rows}</tbody></table></div></section>
<section id="findings"><div class="eyebrow">Evidence-led review</div><h2>Detailed findings</h2><p class="small">A reproduced component behavior is distinguished from a full exploit. Source links point to the reviewed commit; excerpts remain available offline. Recommendations have not been applied.</p><div class="filters"><label>Search findings<br><input id="search" type="search" placeholder="Search a component, risk or finding ID…"></label><label>Severity<br><select id="severity"><option value="">All severities</option><option value="critical">Critical</option><option value="high">High</option><option value="medium">Medium</option></select></label><span id="result-count" role="status" aria-live="polite">13 of 13 findings</span></div>{''.join(cards)}<p id="empty" class="no-results" hidden>No findings match these filters.</p></section>
<section id="remediation"><div class="eyebrow">Recommended order</div><h2>Make the privilege model match the controls.</h2><div class="roadmap"><div><span class="phase">01 / CONTAIN EXPOSURE</span><h3>Restrict dangerous deployment paths</h3><p>Limit Nix builds and raw host mounts to fully trusted administrators until isolation is implemented. Upgrade the bundled runtime and deployed netproxy binaries.</p><p class="small">OD-01, OD-02, OD-03, OD-08 · owners: runtime, installer and release</p></div><div><span class="phase">02 / ENFORCE AUTHORITY</span><h3>Bind access to exact identities</h3><p>Constrain certificate names, define secret-use and trusted-code permissions, scope worker repository credentials, and make worker key revocation effective.</p><p class="small">OD-04–OD-07 · owners: authorization, PKI and credentials</p></div><div><span class="phase">03 / HARDEN AND VERIFY</span><h3>Bound work and close regressions</h3><p>Add global hash admission and listener deadlines, restrict registry redirects, repair passkey persistence, and clear development dependency alerts.</p><p class="small">OD-09–OD-13 · owners: API, authentication and frontend</p></div></div><p class="dependency-note">If a finding was exploitable in an environment, fixing code alone does not remove previously copied credentials, issued certificates or modified host state. Use the finding's affected trust boundary to decide what needs replacement or investigation; this audit found no evidence of an actual intrusion.</p></section>
<section id="dependencies" class="dependencies"><div class="eyebrow">Dependency triage</div><h2>Version matches are not all application exploits.</h2><p>govulncheck v1.8.0 completed source scans for the host and Linux/amd64 using Go 1.27.0 and a vulnerability database last modified 10 September 2026. Both reported <strong>10 advisories with symbol-level traces</strong> and 36 advisories at module level. These counts overlap; they are not additive. The 10 traces were triaged below. The tool's JSON mode exited successfully while emitting findings.</p><p class="dependency-note">The runtime is a separate inventory: <strong>Go client library containerd v2.3.1</strong>, <strong>bundled daemon 2.0.5</strong>, <strong>bundled runc 1.2.6</strong>. A source scan does not inspect those downloaded binaries. OD-03 records the independently checked runtime advisories. {refs([('How govulncheck works','https://go.dev/doc/tutorial/govulncheck')])}</p>
<div class="table-wrap"><table><thead><tr><th>Go advisory</th><th>Module / reported fixed version</th><th>OpenDeploy applicability</th></tr></thead><tbody>{''.join(go_rows)}</tbody></table></div>
<p class="small" style="margin-top:15px">Fixed versions above come from the selected scanner trace and may differ by supported branch. Use each upstream advisory and current supported releases when choosing upgrades. No CRI checkpoint, xDS, normalization or EventStream exploit is claimed.</p>
<details><summary>Frontend advisory inventory — 14 alerts <span>8 high · 6 moderate · development/build tree</span></summary><p class="dependency-note">All reported paths pass through Vite. The application-specific assessment is OD-13; this table preserves upstream severity and reported patch ranges without equating them to deployed application severity.</p><div class="table-wrap"><table><thead><tr><th>Package / installed</th><th>Advisory</th><th>Upstream severity</th><th>Reported patched range</th></tr></thead><tbody>{''.join(npm_rows)}</tbody></table></div></details></section>
<section id="coverage"><div class="eyebrow">Scope and verification</div><h2>What was checked, and what remains open.</h2><div class="checks"><div><h3>Checks completed</h3><ul><li><strong>8 audit reproductions passed</strong> across 4 real Go packages using overlays. These reproduced 5 finding groups: mounts, workload PKI, secret delegation, registry URLs and credential persistence.</li><li><strong>14 existing Go package suites passed</strong> with <code>-count=1</code>, covering authorization, handlers, deployments, PKI, secrets, rate limiting, Git, registry authentication, runners, network logic and workers.</li><li><strong>138 frontend tests passed</strong>, with no failures or skips.</li><li><strong>Dependency scans completed</strong> for Go host/Linux targets and the frontend lockfile, with findings preserved and triaged.</li></ul><p class="small">Audit checks use synthetic values, temporary databases and loopback HTTP. PASS means the reported behavior exists. Tests do not start deployed workloads or prove Linux exploitability.</p></div><div><h3>Controls verified in the reviewed paths</h3><ul><li>Bearer authentication and entity/space authorization are wired into the production web handler. Personal and agent session hashes and revocation checks exist.</li><li>WebAuthn requires user verification; cluster TLS requires client certificates and TLS 1.3. Enrollment's custom TLS verifier pins the server SPKI.</li><li>Worker secret/config/asset access and status writes are checked against assignments.</li><li>Static UI responses set CSP, frame denial, nosniff and other browser headers. No direct DOM injection sink was identified in the reviewed frontend paths.</li><li>Configured GitHub credentials are now supplied outside Git URLs/argv and scoped to GitHub. GHCR's transport strips credentials on untrusted destinations.</li></ul></div></div>
<div class="checks" style="margin-top:22px"><div><h3>Limits and follow-up work</h3><ul><li>No deployed host, firewall, reverse-proxy policy or running binary inventory was available. No production traffic or data was inspected.</li><li>Tests ran on macOS; Linux source scanning is not Linux execution. Mount confinement, network enforcement and runtime escapes require isolated VM validation.</li><li>Full repository test suite, complete Git-history secret scanning, exhaustive route fuzzing and all secondary example/doc dependency projects were outside this pass.</li><li>Container CPU/memory/PID budgets, disk/asset/log quotas, backup authenticity and restore quarantine warrant separate adversarial tests.</li><li>Host-network mode and workload-to-host traffic need an explicit policy model. Current nftables construction has forwarding chains; no workload INPUT filter was found. Host-network selection remains available in deployment specs.</li><li>Review token-response <code>Cache-Control: no-store</code>, recent authentication for passkey enrollment, and revocation/expiry handling for already-open streams.</li></ul><p class="small">These follow-ups are not included in the 13 finding count and are not represented as demonstrated exploits.</p></div><div><h3>Changes since the earlier reviews</h3><p>July reviews were used as leads, then checked against current code. This report does not mark every historical item closed.</p><p>Personal-session inventory/revocation now exists; Git token URL persistence and GHCR cross-host credential forwarding are improved; worker renewal and per-veth source-validation structures have been added.</p><p>Nix exporter execution, host-mount confinement, broad worker GitHub credentials and pre-request resource controls remain material concerns. Workload PKI aliases and indirect agent secret access expose additional gaps in the current permission model.</p><p class="small">Reviewed baseline: <code>{COMMIT}</code>. The review began at 63234683f8a6. A containerd restart-handling commit arrived during the audit; its delta was reviewed and the affected runner tests and audit reproductions were rerun. Dependency scans preceded that final delta; the relevant dependencies and vulnerable call sites were unchanged. Existing dirty user-docs work was not used as evidence for application findings.</p></div></div>
<h3 style="margin-top:28px">Reproduction and evidence</h3><p>Run the bounded checks from the repository root:</p><pre><code>python3 docs/security-reviews/2026-09-11-evidence/reproduce.py</code></pre><p class="small">The script injects temporary Go test files with <code>-overlay</code>; it leaves application source unchanged. Report findings and excerpts are embedded in this HTML. Companion evidence files are optional for reading the report and should accompany it when sharing the raw results.</p><div class="evidence-links">{''.join(f'<a href="2026-09-11-evidence/{name}">{label}</a>' for name,label in [('reproduce.py','Reproduction script'),('reproduction-results.txt','Audit test results'),('go-tests.txt','Go test results'),('frontend-tests.txt','Frontend test results'),('govulncheck-linux-summary.json','Go/Linux scan summary'),('govulncheck-summary.json','Go/host scan summary'),('pnpm-audit.json','Raw frontend audit'),('govulncheck-linux.json.gz','Raw Go/Linux audit (gzip)'),('govulncheck.json.gz','Raw Go/host audit (gzip)'),('manifest.json','Evidence manifest')])}</div></section>
</main><footer class="shell">Prepared by Codex from the local OpenDeploy repository. Assessment date: 11 September 2026. Findings describe the reviewed revision and stated assumptions; no remediation or deployment was performed. This HTML uses no external scripts, fonts or analytics.</footer><script>{JS}</script></body></html>'''

OUT.write_text(document)
(EVIDENCE / 'findings.json').write_text(json.dumps({'commit':COMMIT,'date':'2026-09-11','findings':FINDINGS},indent=2)+'\n')
